1	<script lang="ts">
2		/**
3		 * HierarchyEditor — presentational tree for the spending-hierarchy editor.
4		 *
5		 * Pure: props in, callbacks out. It renders the Importance → Grouping →
6		 * Category tree (plus the "Unassigned categories" bucket) and emits
7		 * `onAssignCategory` / `onMoveGroup` when a select changes. The page owns data
8		 * loading and the CategoryService mutations; this component owns none of that,
9		 * so it renders under the vitest-browser harness without a Supabase mock.
10		 *
11		 * Design: docs/plans/2026-07-09-spending-report-design.md
12		 */
13	
14		import type { HierarchyTree } from '$lib/utils/hierarchyTree';
15		import type { ImportanceArea } from '$lib/types/Hierarchy';
16	
17		interface Props {
18			tree: HierarchyTree;
19			importanceAreas: ImportanceArea[];
20			saving?: boolean;
21			/** groupId is null when the category is set back to Uncategorized. */
22			onAssignCategory: (categoryId: string, groupId: string | null) => void;
23			onMoveGroup: (groupId: string, importanceAreaId: string) => void;
24			onCreateGroup: (name: string, importanceAreaId: string) => void;
25			onRenameGroup: (groupId: string, name: string) => void;
26		}
27	
28		let {
29			tree,
30			importanceAreas,
31			saving = false,
32			onAssignCategory,
33			onMoveGroup,
34			onCreateGroup,
35			onRenameGroup
36		}: Props = $props();
37	
38		// Presentational-only state: which Grouping is being renamed, and the pending
39		// text for the rename input and the "Add a Grouping" form.
40		let editingGroupId = $state<string | null>(null);
41		let editName = $state('');
42		let newGroupName = $state('');
43		let newGroupImportanceId = $state('');
44	
45		function startRename(groupId: string, currentName: string) {
46			editingGroupId = groupId;
47			editName = currentName;
48		}
49	
50		function cancelRename() {
51			editingGroupId = null;
52			editName = '';
53		}
54	
55		function submitRename(groupId: string) {
56			const name = editName.trim();
57			if (!name) return;
58			onRenameGroup(groupId, name);
59			cancelRename();
60		}
61	
62		function submitNewGroup() {
63			const name = newGroupName.trim();
64			if (!name || !newGroupImportanceId) return;
65			onCreateGroup(name, newGroupImportanceId);
66			newGroupName = '';
67			newGroupImportanceId = '';
68		}
69	</script>
70	
71	{#snippet groupPicker(categoryId: string, currentGroupId: string | null)}
72		<!-- Options grouped by Importance so a category can be moved anywhere. -->
73		<select
74			class="rounded border border-gray-300 bg-white py-1 pr-8 pl-2 text-sm disabled:opacity-50"
75			value={currentGroupId ?? ''}
76			disabled={saving}
77			aria-label="Grouping for this category"
78			onchange={(e) => onAssignCategory(categoryId, e.currentTarget.value || null)}
79		>
80			<option value="">Uncategorized (no grouping)</option>
81			{#each tree.importances as node (node.importance.id)}
82				{#if node.importance.id}
83					<optgroup label={node.importance.name}>
84						{#each node.groups as g (g.group.id)}
85							<option value={g.group.id}>{g.group.name}</option>
86						{/each}
87					</optgroup>
88				{/if}
89			{/each}
90		</select>
91	{/snippet}
92	
93	{#if tree.unassigned.length > 0}
94		<section class="mb-6 rounded border border-amber-200 bg-amber-50 p-4" data-testid="unassigned">
95			<h2 class="mb-1 text-lg font-semibold text-amber-900">
96				Unassigned categories ({tree.unassigned.length})
97			</h2>
98			<p class="mb-3 text-sm text-amber-800">
99				These roll up to Uncategorized in the report. Assign each to a Grouping.
100			</p>
101			<ul class="divide-y divide-amber-100">
102				{#each tree.unassigned as category (category.id)}
103					<li class="flex flex-wrap items-center justify-between gap-2 py-2">
104						<span class="text-sm font-medium text-gray-800">{category.name}</span>
105						{@render groupPicker(category.id, category.group_id ?? null)}
106					</li>
107				{/each}
108			</ul>
109		</section>
110	{/if}
111	
112	<div class="space-y-6">
113		{#each tree.importances as node (node.importance.id)}
114			<section class="rounded border border-gray-200">
115				<h2 class="rounded-t bg-indigo-100 px-4 py-2 text-lg font-semibold text-indigo-900">
116					{node.importance.name}
117				</h2>
118				{#if node.groups.length === 0}
119					<p class="px-4 py-3 text-sm text-gray-500">No groupings in this area yet.</p>
120				{:else}
121					<div class="divide-y divide-gray-200">
122						{#each node.groups as g (g.group.id)}
123							<div class="p-4">
124								<div class="mb-2 flex flex-wrap items-center justify-between gap-2">
125									{#if editingGroupId === g.group.id}
126										<div class="flex items-center gap-2">
127											<input
128												class="rounded border border-gray-300 px-2 py-1 text-sm"
129												bind:value={editName}
130												aria-label="Rename grouping"
131												disabled={saving}
132											/>
133											<button
134												type="button"
135												class="rounded bg-indigo-600 px-2 py-1 text-sm text-white hover:bg-indigo-700 disabled:opacity-50"
136												onclick={() => submitRename(g.group.id)}
137												disabled={saving || editName.trim() === ''}
138											>
139												Save
140											</button>
141											<button
142												type="button"
143												class="rounded border border-gray-300 px-2 py-1 text-sm hover:bg-gray-100 disabled:opacity-50"
144												onclick={cancelRename}
145												disabled={saving}
146											>
147												Cancel
148											</button>
149										</div>
150									{:else}
151										<div class="flex items-center gap-2">
152											<h3 class="font-medium text-gray-800">{g.group.name}</h3>
153											<button
154												type="button"
155												class="rounded border border-gray-300 px-2 py-0.5 text-xs text-gray-600 hover:bg-gray-100 disabled:opacity-50"
156												onclick={() => startRename(g.group.id, g.group.name)}
157												aria-label={`Rename ${g.group.name}`}
158												disabled={saving}
159											>
160												Rename
161											</button>
162										</div>
163									{/if}
164									<label class="flex items-center gap-2 text-sm text-gray-600">
165										<span>Area of Importance</span>
166										<select
167											class="rounded border border-gray-300 bg-white py-1 pr-8 pl-2 text-sm disabled:opacity-50"
168											value={g.group.importance_area_id}
169											disabled={saving}
170											onchange={(e) => onMoveGroup(g.group.id, e.currentTarget.value)}
171										>
172											{#each importanceAreas as area (area.id)}
173												<option value={area.id}>{area.name}</option>
174											{/each}
175										</select>
176									</label>
177								</div>
178								{#if g.categories.length === 0}
179									<p class="text-sm text-gray-500">No categories in this grouping.</p>
180								{:else}
181									<ul class="divide-y divide-gray-100">
182										{#each g.categories as category (category.id)}
183											<li class="flex flex-wrap items-center justify-between gap-2 py-2 pl-4">
184												<span class="text-sm text-gray-800">{category.name}</span>
185												{@render groupPicker(category.id, category.group_id ?? null)}
186											</li>
187										{/each}
188									</ul>
189								{/if}
190							</div>
191						{/each}
192					</div>
193				{/if}
194			</section>
195		{/each}
196	</div>
197	
198	<!-- Add a Grouping. Importance attaches to the Grouping, so the area is chosen
199	     here; the new (empty) group then appears above, ready to have categories
200	     assigned into it. No delete — an empty Grouping is inert (report suppresses
201	     zero-activity rows). -->
202	<section class="mt-6 rounded border border-gray-200 p-4" data-testid="add-group">
203		<h2 class="mb-3 text-lg font-semibold text-gray-800">Add a Grouping</h2>
204		<div class="flex flex-wrap items-end gap-3">
205			<label class="flex flex-col gap-1 text-sm text-gray-600">
206				<span>Name</span>
207				<input
208					class="rounded border border-gray-300 px-2 py-1 text-sm"
209					bind:value={newGroupName}
210					aria-label="New grouping name"
211					placeholder="e.g. Pets"
212					disabled={saving}
213				/>
214			</label>
215			<label class="flex flex-col gap-1 text-sm text-gray-600">
216				<span>Area of Importance</span>
217				<select
218					class="rounded border border-gray-300 bg-white py-1 pr-8 pl-2 text-sm disabled:opacity-50"
219					bind:value={newGroupImportanceId}
220					aria-label="Area of Importance for the new grouping"
221					disabled={saving}
222				>
223					<option value="">Choose an area…</option>
224					{#each importanceAreas as area (area.id)}
225						<option value={area.id}>{area.name}</option>
226					{/each}
227				</select>
228			</label>
229			<button
230				type="button"
231				class="rounded bg-indigo-600 px-3 py-1.5 text-sm text-white hover:bg-indigo-700 disabled:opacity-50"
232				onclick={submitNewGroup}
233				disabled={saving || newGroupName.trim() === '' || newGroupImportanceId === ''}
234			>
235				Add grouping
236			</button>
237		</div>
238	</section>
