1	<script lang="ts">
2		/**
3		 * Spending hierarchy editor
4		 *
5		 * Lets the family maintainer restructure the spending hierarchy without SQL:
6		 *   - assign a Category to a Grouping (or back to Uncategorized)
7		 *   - move a Grouping to a different Area of Importance
8		 *   - add a new Grouping under an Area of Importance
9		 *   - rename a Grouping
10		 *
11		 * The report attaches Importance to the Grouping, so moving a Grouping
12		 * re-buckets all its Categories at once. Categories with no Grouping land in
13		 * the "Unassigned" bucket up top — the whole reason this editor exists (the
14		 * seed maps categories by name, so custom/renamed ones start unassigned).
15		 *
16		 * Tree shaping is the pure `buildHierarchyTree`; this page loads the three
17		 * hierarchy tables, renders the tree, and calls CategoryService mutations,
18		 * reloading after each. Design: docs/plans/2026-07-09-spending-report-design.md
19		 */
20	
21		import { onMount } from 'svelte';
22		import { resolve } from '$app/paths';
23		import { supabase } from '$lib/supabaseClient';
24		import { CategoryService } from '$lib/services/CategoryService';
25		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
26		import { buildHierarchyTree, type HierarchyTree } from '$lib/utils/hierarchyTree';
27		import HierarchyEditor from '$lib/components/HierarchyEditor.svelte';
28		import type { ImportanceArea } from '$lib/types/Hierarchy';
29		import type { Session } from '@supabase/supabase-js';
30	
31		let session: Session | null = $state(null);
32		let familyId: string | null = $state(null);
33		let loading = $state(true);
34		let saving = $state(false);
35		let error: string | null = $state(null);
36		let tree = $state<HierarchyTree | null>(null);
37		let importanceAreas = $state<ImportanceArea[]>([]);
38	
39		const service = new CategoryService(supabase);
40	
41		onMount(async () => {
42			const { data } = await supabase.auth.getSession();
43			session = data.session;
44			if (!session) {
45				loading = false;
46				return;
47			}
48	
49			familyId = await getDefaultFamilyId();
50			if (!familyId) {
51				error = 'No family found. Please contact support.';
52				loading = false;
53				return;
54			}
55	
56			await load();
57		});
58	
59		async function load() {
60			if (!familyId) return;
61	
62			try {
63				loading = true;
64				error = null;
65	
66				// Self-seed the default hierarchy if this family has none yet (mirrors
67				// the /spending report's lazy-init), so the editor is never empty.
68				let areas = await service.getFamilyImportanceAreas(familyId);
69				if (areas.length === 0) {
70					await service.createDefaultHierarchy(familyId);
71					areas = await service.getFamilyImportanceAreas(familyId);
72				}
73	
74				const [groups, categories] = await Promise.all([
75					service.getFamilyGroups(familyId),
76					service.getFamilyCategories(familyId)
77				]);
78	
79				importanceAreas = areas;
80				tree = buildHierarchyTree(areas, groups, categories);
81			} catch (err) {
82				console.error('Error loading hierarchy:', err);
83				error = err instanceof Error ? err.message : 'Failed to load the hierarchy';
84			} finally {
85				loading = false;
86			}
87		}
88	
89		/** Run a mutation, surface any error in the UI, then reload the tree. */
90		async function mutate(action: () => Promise<void>) {
91			try {
92				saving = true;
93				error = null;
94				await action();
95				await load();
96			} catch (err) {
97				console.error('Error saving hierarchy change:', err);
98				error = err instanceof Error ? err.message : 'Failed to save the change';
99			} finally {
100				saving = false;
101			}
102		}
103	
104		function assignCategory(categoryId: string, groupId: string | null) {
105			mutate(() => service.assignCategoryToGroup(categoryId, groupId));
106		}
107	
108		function moveGroup(groupId: string, importanceAreaId: string) {
109			if (!importanceAreaId) return;
110			mutate(() => service.moveGroupToImportance(groupId, importanceAreaId));
111		}
112	
113		function createGroup(name: string, importanceAreaId: string) {
114			const fid = familyId;
115			if (!fid || !name.trim() || !importanceAreaId) return;
116			mutate(async () => {
117				await service.createGroup(fid, name, importanceAreaId);
118			});
119		}
120	
121		function renameGroup(groupId: string, name: string) {
122			if (!name.trim()) return;
123			mutate(() => service.renameGroup(groupId, name));
124		}
125	
126		const hasHierarchy = $derived(tree !== null && tree.importances.length > 0);
127	</script>
128	
129	<svelte:head>
130		<title>Edit spending hierarchy — YFL Expense Tracker</title>
131	</svelte:head>
132	
133	<div class="hierarchy-editor max-w-5xl">
134		<div class="mb-6 flex flex-wrap items-center justify-between gap-3">
135			<div>
136				<h1 class="mb-2 text-2xl font-bold">Edit spending hierarchy</h1>
137				<p class="text-gray-600">
138					Assign each Category to a Grouping, and each Grouping to an Area of Importance. Add or
139					rename Groupings as needed. Changes save immediately and reshape the Spending report.
140				</p>
141			</div>
142			<a
143				href={resolve('/spending')}
144				class="rounded border border-gray-300 px-3 py-1 text-sm hover:bg-gray-100"
145			>
146				← Back to Spending
147			</a>
148		</div>
149	
150		{#if error}
151			<div class="mb-4 rounded border border-red-200 bg-red-50 p-4 text-red-700">{error}</div>
152		{/if}
153	
154		{#if loading}
155			<div class="flex items-center justify-center p-8 text-gray-500">Loading hierarchy…</div>
156		{:else if !session}
157			<div class="rounded border border-gray-200 bg-gray-50 p-8 text-center text-gray-500">
158				Please log in to edit the hierarchy.
159			</div>
160		{:else if !hasHierarchy}
161			<div class="rounded border border-gray-200 bg-gray-50 p-8 text-center text-gray-500">
162				No hierarchy found for this family.
163			</div>
164		{:else if tree}
165			<HierarchyEditor
166				{tree}
167				{importanceAreas}
168				{saving}
169				onAssignCategory={assignCategory}
170				onMoveGroup={moveGroup}
171				onCreateGroup={createGroup}
172				onRenameGroup={renameGroup}
173			/>
174		{/if}
175	</div>
176

1	import { describe, it, expect, vi } from 'vitest';
2	import { tick } from 'svelte';
3	import { render } from 'vitest-browser-svelte';
4	import HierarchyEditor from './HierarchyEditor.svelte';
5	import { buildHierarchyTree } from '$lib/utils/hierarchyTree';
6	import type { Category } from '$lib/types/Category';
7	import type { CategoryGroup, ImportanceArea } from '$lib/types/Hierarchy';
8	
9	/**
10	 * Render tests for the presentational <HierarchyEditor>. Tree shaping is
11	 * unit-tested in hierarchyTree.spec.ts; these prove the component renders the
12	 * unassigned bucket, the Importance sections, and — the interaction — emits
13	 * onAssignCategory / onMoveGroup with the right ids when a select changes.
14	 */
15	
16	const importanceAreas: ImportanceArea[] = [
17		{ id: 'imp-ess', name: 'Essential', sort_order: 1 },
18		{ id: 'imp-pri', name: 'Priorities', sort_order: 2 }
19	];
20	const groups: CategoryGroup[] = [
21		{ id: 'grp-everyday', name: 'Everyday', importance_area_id: 'imp-ess' },
22		{ id: 'grp-kids', name: 'Kids', importance_area_id: 'imp-pri' }
23	];
24	function cat(id: string, name: string, group_id: string | null): Category {
25		return { id, name, color: null, group_id };
26	}
27	const categories: Category[] = [
28		cat('cat-groceries', 'Groceries', 'grp-everyday'),
29		cat('cat-allowance', 'Allowance', 'grp-kids'),
30		cat('cat-orphan', 'Mystery Spend', null)
31	];
32	
33	function renderEditor(
34		overrides: {
35			onAssignCategory?: (categoryId: string, groupId: string | null) => void;
36			onMoveGroup?: (groupId: string, importanceAreaId: string) => void;
37			onCreateGroup?: (name: string, importanceAreaId: string) => void;
38			onRenameGroup?: (groupId: string, name: string) => void;
39		} = {}
40	) {
41		return render(HierarchyEditor, {
42			tree: buildHierarchyTree(importanceAreas, groups, categories),
43			importanceAreas,
44			saving: false,
45			onAssignCategory: overrides.onAssignCategory ?? (() => {}),
46			onMoveGroup: overrides.onMoveGroup ?? (() => {}),
47			onCreateGroup: overrides.onCreateGroup ?? (() => {}),
48			onRenameGroup: overrides.onRenameGroup ?? (() => {})
49		});
50	}
51	
52	describe('HierarchyEditor', () => {
53		it('renders the unassigned bucket with a count and its category', async () => {
54			const screen = renderEditor();
55			const bucket = screen.baseElement.querySelector('[data-testid="unassigned"]');
56			expect(bucket).not.toBeNull();
57			expect(bucket?.textContent).toContain('Unassigned categories (1)');
58			expect(bucket?.textContent).toContain('Mystery Spend');
59		});
60	
61		it('renders an Importance section per area with its groupings', async () => {
62			const screen = renderEditor();
63			const text = screen.baseElement.textContent ?? '';
64			expect(text).toContain('Essential');
65			expect(text).toContain('Priorities');
66			expect(text).toContain('Everyday');
67			expect(text).toContain('Kids');
68		});
69	
70		it('emits onAssignCategory with the group id when an unassigned category is assigned', async () => {
71			const onAssignCategory = vi.fn();
72			const screen = renderEditor({ onAssignCategory });
73	
74			const bucket = screen.baseElement.querySelector('[data-testid="unassigned"]');
75			const select = bucket?.querySelector('select') as HTMLSelectElement;
76			select.value = 'grp-everyday';
77			select.dispatchEvent(new Event('change', { bubbles: true }));
78	
79			expect(onAssignCategory).toHaveBeenCalledWith('cat-orphan', 'grp-everyday');
80		});
81	
82		it('emits onAssignCategory with null when a category is set back to Uncategorized', async () => {
83			const onAssignCategory = vi.fn();
84			const screen = renderEditor({ onAssignCategory });
85	
86			// The first non-bucket grouping select belongs to a categorized category.
87			const selects = Array.from(
88				screen.baseElement.querySelectorAll('select[aria-label="Grouping for this category"]')
89			) as HTMLSelectElement[];
90			// Groceries (in Everyday) is the first category select outside the amber bucket.
91			const groceries = selects.find(
92				(s) => s.value === 'grp-everyday' && !s.closest('[data-testid="unassigned"]')
93			);
94			expect(groceries).toBeDefined();
95			groceries!.value = '';
96			groceries!.dispatchEvent(new Event('change', { bubbles: true }));
97	
98			expect(onAssignCategory).toHaveBeenCalledWith('cat-groceries', null);
99		});
100	
101		it('emits onMoveGroup when a grouping is moved to another Importance', async () => {
102			const onMoveGroup = vi.fn();
103			const screen = renderEditor({ onMoveGroup });
104	
105			// The grouping's Importance select has options that are Importance names.
106			const importanceSelects = Array.from(screen.baseElement.querySelectorAll('select')).filter(
107				(s) => Array.from(s.options).some((o) => o.textContent === 'Essential')
108			) as HTMLSelectElement[];
109			// The Kids grouping currently sits in Priorities; move it to Essential.
110			const kidsSelect = importanceSelects.find((s) => s.value === 'imp-pri');
111			expect(kidsSelect).toBeDefined();
112			kidsSelect!.value = 'imp-ess';
113			kidsSelect!.dispatchEvent(new Event('change', { bubbles: true }));
114	
115			expect(onMoveGroup).toHaveBeenCalledWith('grp-kids', 'imp-ess');
116		});
117	
118		it('emits onCreateGroup with the typed name and chosen Importance', async () => {
119			const onCreateGroup = vi.fn();
120			const screen = renderEditor({ onCreateGroup });
121	
122			const form = screen.baseElement.querySelector('[data-testid="add-group"]') as HTMLElement;
123			const nameInput = form.querySelector(
124				'input[aria-label="New grouping name"]'
125			) as HTMLInputElement;
126			const areaSelect = form.querySelector(
127				'select[aria-label="Area of Importance for the new grouping"]'
128			) as HTMLSelectElement;
129	
130			nameInput.value = 'Pets';
131			nameInput.dispatchEvent(new Event('input', { bubbles: true }));
132			areaSelect.value = 'imp-pri';
133			areaSelect.dispatchEvent(new Event('change', { bubbles: true }));
134			await tick();
135	
136			const addButton = Array.from(form.querySelectorAll('button')).find(
137				(b) => b.textContent?.trim() === 'Add grouping'
138			) as HTMLButtonElement;
139			expect(addButton.disabled).toBe(false);
140			addButton.click();
141	
142			expect(onCreateGroup).toHaveBeenCalledWith('Pets', 'imp-pri');
143		});
144	
145		it('keeps Add grouping disabled until a name and an area are both set', async () => {
146			const screen = renderEditor();
147			const form = screen.baseElement.querySelector('[data-testid="add-group"]') as HTMLElement;
148			const addButton = Array.from(form.querySelectorAll('button')).find(
149				(b) => b.textContent?.trim() === 'Add grouping'
150			) as HTMLButtonElement;
