1	/**
2	 * Route/layout render harness — controllable mocks for the SvelteKit + Supabase
3	 * module boundaries a `+page.svelte` / `+layout.svelte` touches on mount.
4	 *
5	 * Why this exists: route components import `$app/stores` (the `page` store) and
6	 * `$lib/supabaseClient` (a module-level Supabase singleton created at import time,
7	 * which throws / hits the network in a test). Both must be replaced before the
8	 * component is imported. A spec wires them up once at the top:
9	 *
10	 *     import { pageStore, supabaseMock, setRoute, setSession, resetHarness }
11	 *         from '$lib/tests/harness/appMocks';
12	 *     vi.mock('$app/stores', () => ({ page: pageStore }));
13	 *     vi.mock('$lib/supabaseClient', () => ({ supabase: supabaseMock }));
14	 *     beforeEach(resetHarness);
15	 *
16	 * Then each test drives state with setRoute()/setSession() BEFORE render().
17	 *
18	 * These are hand-built (not the real client) so tests stay pure — no network, no
19	 * env, no auth/seed harness. See docs/product-backlog.md → Test-suite cleanup.
20	 */
21	import { writable } from 'svelte/store';
22	import type { Session } from '@supabase/supabase-js';
23	import type { ReceiptRow } from '$lib/models/Receipt';
24	import type { Expense } from '$lib/services/ExpenseService';
25	import type { Category } from '$lib/types/Category';
26	
27	/** Minimal shape the layout/pages read off the `page` store: `$page.url`. */
28	interface PageState {
29		url: URL;
30	}
31	
32	/** Live `page` store — a real Svelte store, so `$page` works in the component. */
33	export const pageStore = writable<PageState>({ url: new URL('http://localhost/') });
34	
35	/** Point the harness at a route. `search` is an optional `?a=b` query string. */
36	export function setRoute(pathname: string, search = ''): void {
37		pageStore.set({ url: new URL(`http://localhost${pathname}${search}`) });
38	}
39	
40	// --- Supabase auth mock -------------------------------------------------------
41	// The layout subscribes via onAuthStateChange and then awaits getSession(). We
42	// keep the current session in a closure and notify subscribers on setSession().
43	
44	type AuthCallback = (event: string, session: Session | null) => void;
45	
46	let currentSession: Session | null = null;
47	let sessionPending = false;
48	const authSubscribers = new Set<AuthCallback>();
49	
50	/**
51	 * Set (or clear) the signed-in session and notify auth subscribers, mirroring a
52	 * real login/logout. Call BEFORE render() to choose the authed/unauthed path.
53	 */
54	export function setSession(session: Session | null): void {
55		currentSession = session;
56		for (const cb of authSubscribers) cb(session ? 'SIGNED_IN' : 'SIGNED_OUT', session);
57	}
58	
59	/** Build a minimal session object for a signed-in user. */
60	export function fakeSession(userId = 'test-user-id'): Session {
61		return {
62			user: { id: userId, email: 'primary@example.com', created_at: '2026-01-01T00:00:00Z' }
63		} as unknown as Session;
64	}
65	
66	/**
67	 * Make getSession() hang, so the layout stays in its pre-auth-check "Loading…"
68	 * state. Use to assert what a user sees before the session resolves.
69	 */
70	export function setSessionPending(): void {
71		sessionPending = true;
72	}
73	
74	// --- profiles table mock -----------------------------------------------------
75	// The profile page reads/writes supabase.from('profiles') directly (no service).
76	// setProfile() controls what the select().eq().single() chain returns; writes
77	// (insert/update) succeed inertly. A null profile yields the PGRST116 "no rows"
78	// error the page treats as "no profile yet".
79	
80	/** A row of the `profiles` table (primary email lives in auth, not here). */
81	export interface ProfileRow {
82		id: string;
83		user_id: string;
84		email_1: string | null;
85		email_2: string | null;
86		email_3: string | null;
87		email_4: string | null;
88		email_5: string | null;
89		created_at: string;
90		updated_at: string;
91	}
92	
93	let profileRow: ProfileRow | null = null;
94	
95	/** Set the row the stubbed `profiles` query returns (null → no profile yet). */
96	export function setProfile(row: ProfileRow | null): void {
97		profileRow = row;
98	}
99	
100	/** Build a profiles row, defaulting every email slot to empty. */
101	export function makeProfile(overrides: Partial<ProfileRow> = {}): ProfileRow {
102		return {
103			id: 'profile-1',
104			user_id: 'test-user-id',
105			email_1: null,
106			email_2: null,
107			email_3: null,
108			email_4: null,
109			email_5: null,
110			created_at: '2026-01-01T00:00:00Z',
111			updated_at: '2026-01-01T00:00:00Z',
112			...overrides
113		};
114	}
115	
116	export const supabaseMock = {
117		from: () => {
118			const builder = {
119				select: () => builder,
120				eq: () => builder,
121				single: async () => ({
122					data: profileRow,
123					error: profileRow ? null : { code: 'PGRST116', message: 'no rows' }
124				}),
125				insert: async () => ({ error: null }),
126				update: () => ({ eq: async () => ({ error: null }) })
127			};
128			return builder;
129		},
130		auth: {
131			getSession: () =>
132				sessionPending
133					? new Promise<never>(() => {})
134					: Promise.resolve({ data: { session: currentSession }, error: null }),
135			getUser: async () => ({ data: { user: currentSession?.user ?? null }, error: null }),
136			onAuthStateChange: (cb: AuthCallback) => {
137				authSubscribers.add(cb);
138				return {
139					data: {
140						subscription: {
141							unsubscribe() {
142								authSubscribers.delete(cb);
143							}
144						}
145					}
146				};
147			},
148			signOut: async () => ({ error: null })
149		}
150	};
151	
152	// --- ReceiptService stub ------------------------------------------------------
153	// The receipts page does `new ReceiptService(supabase)` at module scope and calls
154	// `.list()` on mount to populate its table. Mock the module with this class and
155	// drive its rows via setReceipts():
156	//   vi.mock('$lib/services/ReceiptService', () => ({ ReceiptService: ReceiptServiceStub }));
157	
158	let receiptRows: ReceiptRow[] = [];
159	
160	/** Set the rows the stubbed ReceiptService.list() returns. Call before render(). */
161	export function setReceipts(rows: ReceiptRow[]): void {
162		receiptRows = rows;
163	}
164	
165	export class ReceiptServiceStub {
166		// Constructor ignores the supabase arg the page passes.
167		async list(): Promise<ReceiptRow[]> {
168			return receiptRows;
169		}
170		async delete(): Promise<void> {}
171		async update<T>(_id: string, patch: T): Promise<T> {
172			return patch;
173		}
174		async createManual<T>(value: T): Promise<T> {
175			return value;
176		}
177		async uploadAndCreate(): Promise<null> {
178			return null;
179		}
180		async bulkDeleteReceipts(): Promise<void> {}
181	}
182	
183	// --- ExpenseService stub ------------------------------------------------------
184	// The expenses page does `new ExpenseService(supabase)` and calls getExpenses() on
185	// mount, plus vendor-rule methods during auto-categorization. Drive rows via
186	// setExpenses(); the vendor-rule methods are inert (0 assigned → no reload/toast):
187	//   vi.mock('$lib/services/ExpenseService', () => ({ ExpenseService: ExpenseServiceStub }));
188	
189	let expenseRows: Expense[] = [];
190	
191	/** Set the rows the stubbed ExpenseService.getExpenses() returns. */
192	export function setExpenses(rows: Expense[]): void {
193		expenseRows = rows;
194	}
195	
196	export class ExpenseServiceStub {
197		async getExpenses(): Promise<Expense[]> {
198			return expenseRows;
199		}
200		async applyAllVendorRules(): Promise<number> {
201			return 0;
202		}
203		async applyRuleToVisibleExpenses(): Promise<number> {
204			return 0;
205		}
206		normalizeVendor(name: string): string {
207			return name;
208		}
209		async getVendorRule(): Promise<null> {
210			return null;
211		}
212		async createVendorRule(): Promise<void> {}
213		async assignCategory(): Promise<void> {}
214		async bulkAssignCategory(): Promise<void> {}
215	}
216	
217	// --- CategoryService stub -----------------------------------------------------
218	// Category dropdowns load family categories on mount. Drive via setCategories():
219	//   vi.mock('$lib/services/CategoryService', () => ({ CategoryService: CategoryServiceStub }));
220	
221	let categoryRows: Category[] = [];
222	
223	/** Set the rows the stubbed CategoryService.getFamilyCategories() returns. */
224	export function setCategories(rows: Category[]): void {
225		categoryRows = rows;
226	}
227	
228	export class CategoryServiceStub {
229		async getFamilyCategories(): Promise<Category[]> {
230			return categoryRows;
231		}
232		async createCategory(): Promise<null> {
233			return null;
234		}
235		async createDefaultCategories(): Promise<void> {}
236	}
237	
238	/** Reset all harness state between tests (call in beforeEach). */
239	export function resetHarness(): void {
240		currentSession = null;
241		sessionPending = false;
242		authSubscribers.clear();
243		receiptRows = [];
244		expenseRows = [];
245		categoryRows = [];
246		profileRow = null;
247		setRoute('/');
248	}
