 * env, no auth/seed harness. See docs/product-backlog.md → Test-suite cleanup.
 */
import { writable } from 'svelte/store';
import type { Session } from '@supabase/supabase-js';
import type { ReceiptRow } from '$lib/models/Receipt';
import type { Expense } from '$lib/services/ExpenseService';
import type { Category } from '$lib/types/Category';

/** Minimal shape the layout/pages read off the `page` store: `$page.url`. */
interface PageState {
	url: URL;
}

/** Live `page` store — a real Svelte store, so `$page` works in the component. */
export const pageStore = writable<PageState>({ url: new URL('http://localhost/') });

/** Point the harness at a route. `search` is an optional `?a=b` query string. */
export function setRoute(pathname: string, search = ''): void {
	pageStore.set({ url: new URL(`http://localhost${pathname}${search}`) });
}

// --- Supabase auth mock -------------------------------------------------------
// The layout subscribes via onAuthStateChange and then awaits getSession(). We
// keep the current session in a closure and notify subscribers on setSession().

type AuthCallback = (event: string, session: Session | null) => void;

let currentSession: Session | null = null;
let sessionPending = false;
const authSubscribers = new Set<AuthCallback>();

/**
 * Set (or clear) the signed-in session and notify auth subscribers, mirroring a
 * real login/logout. Call BEFORE render() to choose the authed/unauthed path.
 */
export function setSession(session: Session | null): void {
	currentSession = session;
	for (const cb of authSubscribers) cb(session ? 'SIGNED_IN' : 'SIGNED_OUT', session);
}

/** Build a minimal session object for a signed-in user. */
export function fakeSession(userId = 'test-user-id'): Session {
	return {
		user: { id: userId, email: 'primary@example.com', created_at: '2026-01-01T00:00:00Z' }
	} as unknown as Session;
}

/**
 * Make getSession() hang, so the layout stays in its pre-auth-check "Loading…"
 * state. Use to assert what a user sees before the session resolves.
 */
export function setSessionPending(): void {
	sessionPending = true;
}

// --- profiles table mock -----------------------------------------------------
// The profile page reads/writes supabase.from('profiles') directly (no service).
// setProfile() controls what the select().eq().single() chain returns; writes
// (insert/update) succeed inertly. A null profile yields the PGRST116 "no rows"
// error the page treats as "no profile yet".

/** A row of the `profiles` table (primary email lives in auth, not here). */
export interface ProfileRow {
	id: string;
	user_id: string;
	email_1: string | null;
	email_2: string | null;
	email_3: string | null;
	email_4: string | null;
	email_5: string | null;
	created_at: string;
	updated_at: string;
}

let profileRow: ProfileRow | null = null;

/** Set the row the stubbed `profiles` query returns (null → no profile yet). */
export function setProfile(row: ProfileRow | null): void {
	profileRow = row;
}

/** Build a profiles row, defaulting every email slot to empty. */
export function makeProfile(overrides: Partial<ProfileRow> = {}): ProfileRow {
	return {
		id: 'profile-1',
		user_id: 'test-user-id',
		email_1: null,
		email_2: null,
		email_3: null,
		email_4: null,
		email_5: null,
		created_at: '2026-01-01T00:00:00Z',
		updated_at: '2026-01-01T00:00:00Z',
		...overrides
	};
}

export const supabaseMock = {
	from: () => {
		const builder = {
			select: () => builder,
			eq: () => builder,
			single: async () => ({
				data: profileRow,
				error: profileRow ? null : { code: 'PGRST116', message: 'no rows' }
			}),
			insert: async () => ({ error: null }),
			update: () => ({ eq: async () => ({ error: null }) })
		};
		return builder;
	},
	auth: {
		getSession: () =>
			sessionPending
				? new Promise<never>(() => {})
				: Promise.resolve({ data: { session: currentSession }, error: null }),
		getUser: async () => ({ data: { user: currentSession?.user ?? null }, error: null }),
		onAuthStateChange: (cb: AuthCallback) => {
			authSubscribers.add(cb);
			return {
				data: {
					subscription: {
						unsubscribe() {
							authSubscribers.delete(cb);
						}
					}
				}
			};
		},
		signOut: async () => ({ error: null })
	}
};

// --- ReceiptService stub ------------------------------------------------------
// The receipts page does `new ReceiptService(supabase)` at module scope and calls
// `.list()` on mount to populate its table. Mock the module with this class and
// drive its rows via setReceipts():
//   vi.mock('$lib/services/ReceiptService', () => ({ ReceiptService: ReceiptServiceStub }));

let receiptRows: ReceiptRow[] = [];

/** Set the rows the stubbed ReceiptService.list() returns. Call before render(). */
export function setReceipts(rows: ReceiptRow[]): void {
	receiptRows = rows;
}

export class ReceiptServiceStub {
	// Constructor ignores the supabase arg the page passes.
	async list(): Promise<ReceiptRow[]> {
		return receiptRows;
	}
	async delete(): Promise<void> {}
	async update<T>(_id: string, patch: T): Promise<T> {
		return patch;
	}
	async createManual<T>(value: T): Promise<T> {
		return value;
	}
	async uploadAndCreate(): Promise<null> {
		return null;
	}
	async bulkDeleteReceipts(): Promise<void> {}
}

// --- ExpenseService stub ------------------------------------------------------
// The expenses page does `new ExpenseService(supabase)` and calls getExpenses() on
// mount, plus vendor-rule methods during auto-categorization. Drive rows via
// setExpenses(); the vendor-rule methods are inert (0 assigned → no reload/toast):
//   vi.mock('$lib/services/ExpenseService', () => ({ ExpenseService: ExpenseServiceStub }));

let expenseRows: Expense[] = [];

/** Set the rows the stubbed ExpenseService.getExpenses() returns. */
export function setExpenses(rows: Expense[]): void {
	expenseRows = rows;
}

export class ExpenseServiceStub {
	async getExpenses(): Promise<Expense[]> {
		return expenseRows;
	}
	async applyAllVendorRules(): Promise<number> {
		return 0;
	}
	async applyRuleToVisibleExpenses(): Promise<number> {
		return 0;
	}
	normalizeVendor(name: string): string {
		return name;
	}
	async getVendorRule(): Promise<null> {
		return null;
	}
	async createVendorRule(): Promise<void> {}
	async assignCategory(): Promise<void> {}
	async bulkAssignCategory(): Promise<void> {}
}

// --- CategoryService stub -----------------------------------------------------
// Category dropdowns load family categories on mount. Drive via setCategories():
//   vi.mock('$lib/services/CategoryService', () => ({ CategoryService: CategoryServiceStub }));

let categoryRows: Category[] = [];

/** Set the rows the stubbed CategoryService.getFamilyCategories() returns. */
export function setCategories(rows: Category[]): void {
	categoryRows = rows;
}

export class CategoryServiceStub {
	async getFamilyCategories(): Promise<Category[]> {
		return categoryRows;
	}
	async createCategory(): Promise<null> {
		return null;
	}
	async createDefaultCategories(): Promise<void> {}
}

/** Reset all harness state between tests (call in beforeEach). */
export function resetHarness(): void {
	currentSession = null;
	sessionPending = false;
	authSubscribers.clear();
	receiptRows = [];
	expenseRows = [];
	categoryRows = [];
	profileRow = null;
	setRoute('/');
}

