/**
 * Handle category selection
 * #{#exp2a} Criterion 7
 */
function selectCategory(category: Category) {
	if (!category) return;

	onCategorySelect(category);
	onCategorySelected?.(category);
	closeDropdown();
}

/**
 * Handle keyboard navigation
 * #{#exp2a} Criterion 8
 */
function handleKeyDown(event: KeyboardEvent) {
	const maxIndex = filteredCategories.length - 1;

	switch (event.key) {
		case 'ArrowDown':
			event.preventDefault();
			selectedIndex = selectedIndex < maxIndex ? selectedIndex + 1 : selectedIndex;
			break;

		case 'ArrowUp':
			event.preventDefault();
			selectedIndex = selectedIndex > 0 ? selectedIndex - 1 : selectedIndex;
			break;

		case 'Enter':
			event.preventDefault();
			if (filteredCategories.length > 0 && selectedIndex >= 0) {
				selectCategory(filteredCategories[selectedIndex]);
			}
			break;

		case 'Escape':
			event.preventDefault();
			closeDropdown();
			break;
	}
}

/**
 * Handle click outside to close dropdown
 * #{#exp2a} Criterion 9
 */
function handleClickOutside(event: MouseEvent) {
	const target = event.target as Node | null;
	// Svelte 5 flushes state synchronously after a delegated click handler, so a
	// click that toggles the dropdown's own content (e.g. "Create new category…")
	// detaches its target from the DOM before this document-level listener runs.
	// A detached target is never a genuine outside click — bail so we don't close.
	if (target && !target.isConnected) return;
	if (dropdownElement && !dropdownElement.contains(target)) {
		closeDropdown();
	}
}

/**
 * Setup click outside listener
 */
onMount(() => {
	document.addEventListener('click', handleClickOutside);
	return () => {
		document.removeEventListener('click', handleClickOutside);
	};
});

/**
 * Handle create new category click
 * #{#exp3b} Criterion 2 - Show inline input field
 */
function handleCreateCategory() {
	isInCreationMode = true;
	creationError = null;
	newCategoryName = '';
	newCategoryColor = '';
	newCategoryGroupId = '';

	// Auto-focus name input
	setTimeout(() => {
		nameInputElement?.focus();
	}, 0);
}

/**
 * Cancel inline creation mode
 * #{#exp3b} Criterion 3
 */
function cancelInlineCreation() {
	isInCreationMode = false;
	newCategoryName = '';
	newCategoryColor = '';
	newCategoryGroupId = '';
	creationError = null;
}

/**
 * Validate new category name
 * #{#exp3b} Criteria 8, 9, 10
 */
function validateNewCategory(name: string): { isValid: boolean; error: string | null } {
	const trimmedName = name.trim();

	// Criterion 9: Empty name validation
	if (trimmedName.length === 0) {
		return { isValid: false, error: 'Category name required' };
	}

	// Criterion 10: Max length validation
	if (trimmedName.length > 100) {
		return { isValid: false, error: 'Category name must be 100 characters or less' };
	}

