/**
 * Count the expenses currently linked to a category.
 *
 * Deleting a category leaves its expenses intact but nulls their category
 * (`expense_categories.category_id` is `ON DELETE SET NULL`), so those
 * expenses drop to Uncategorized. The hierarchy editor uses this count to
 * warn the maintainer how many expenses are affected before confirming.
 *
 * @param categoryId - Category ID to count expenses for
 * @returns Number of expenses linked to the category
 */
async countCategoryExpenses(categoryId: string): Promise<number> {
	if (!categoryId) {
		throw new Error('Category ID is required');
	}

	const { data, error } = await this.supabase
		.from('expense_categories')
		.select('receipt_id')
		.eq('category_id', categoryId);

	if (error) {
		throw new Error(error.message);
	}

	return data ? data.length : 0;
}

