// Delete a category entirely. The DB nulls the category on its expenses
// (expense_categories.category_id ON DELETE SET NULL) and cascade-removes any
// vendor rules, so no expense history is lost — but it's irreversible, so we
// confirm first and surface how many expenses will drop to Uncategorized.
async function deleteCategory(categoryId: string, name: string) {
	let count: number | null = null;
	try {
		count = await service.countCategoryExpenses(categoryId);
	} catch {
		// If the count can't be fetched, fall back to a generic warning rather
		// than blocking the delete.
		count = null;
	}

	const impact =
		count === null
			? 'Any expenses using it will become Uncategorized'
			: count === 0
				? 'It has no expenses'
				: `Its ${count} expense${count === 1 ? '' : 's'} will become Uncategorized`;

	if (
		!confirm(
			`Delete the category “${name}”? ${impact}, and any vendor auto-categorization rules for it will be removed. This can’t be undone.`
		)
	) {
		return;
	}

	await mutate(() => service.deleteCategory(categoryId));
}

