// single-row flow (handleCategorySelect), this deliberately does NOT auto-create
// a vendor rule: a multi-row selection spans many merchants, so there is no one
// merchant to attach a rule to.
async function recategorizeSelected(category: Category): Promise<void> {
	const receiptIds = Array.from(expenseSelection.selected);
	if (receiptIds.length === 0) return;

	isRecategorizing = true;
	error = null;
	try {
		const expenseService = new ExpenseService(supabase);
		await expenseService.bulkAssignCategory(receiptIds, category.id, 'manual');
		expenseSelection = emptySelection();
		await loadExpenses();
		showToast(
			`Set ${receiptIds.length} expense${receiptIds.length === 1 ? '' : 's'} to ${category.name}`,
			'success'
		);
	} catch (err) {
		error = err instanceof Error ? err.message : 'Failed to recategorize expenses';
	} finally {
		isRecategorizing = false;
	}
}

