input.new_string:
 * @param categoryId - Category ID to count expenses for
 * @returns Number of expenses linked to the category
 */
async countCategoryExpenses(categoryId: string): Promise<number> {
	if (!categoryId) {
		throw new Error('Category ID is required');
	}

	// Ask PostgREST for an exact count with `head: true` (no rows returned).
	// A plain select would be capped at the default 1000-row limit, so a
	// category with more than 1000 expenses would undercount — the same cap
	// ExpenseService.getExpenses had to page around.
	const { count, error } = await this.supabase
		.from('expense_categories')
		.select('receipt_id', { count: 'exact', head: true })
		.eq('category_id', categoryId);

	if (error) {
		throw new Error(error.message);
	}

	return count ?? 0;
}

